#!/usr/bin/env bash
# claude-stack — cloud environment setup script.
# Paste into claude.ai/code -> environment menu -> Edit -> "Setup script".
# Runs as root before Claude Code starts; the resulting filesystem is cached (~7 days or
# until this script changes). Constraints: finish < ~5 min, always exit 0.
# GENERATED by scripts/build.sh from scripts/setup-script.tmpl.sh + global/CLAUDE.md — edit those.
set -uo pipefail
log() { echo "[claude-stack] $*"; }

# 1) Global working agreement, loaded as user instructions in every cloud session.
mkdir -p "$HOME/.claude"
cat > "$HOME/.claude/CLAUDE.md" <<'CLAUDE_MD_EOF'
@@GLOBAL_CLAUDE_MD@@
CLAUDE_MD_EOF

# 2) CLI tools the base image lacks (parallel, best-effort).
export DEBIAN_FRONTEND=noninteractive
{
  apt-get update -qq && apt-get install -y -qq --no-install-recommends fd-find shellcheck shfmt tree sqlite3 just >/dev/null \
    && ln -sf "$(command -v fdfind)" /usr/local/bin/fd
} || log "apt tools skipped" &
{ npm install -g --silent @ast-grep/cli >/dev/null 2>&1; } || log "ast-grep skipped" &
wait

# 3) This repo, so any session can run: python3 /opt/claude-stack/scripts/apply-template.py .
#    Best-effort: works when the repo is public or the environment can read it.
if git clone -q --depth 1 https://github.com/ogmachine/claude-stack /opt/claude-stack.new 2>/dev/null; then
  rm -rf /opt/claude-stack && mv /opt/claude-stack.new /opt/claude-stack
else
  log "claude-stack clone skipped (private repo or no access)"
fi

# 4) Git defaults that prevent common agent footguns.
git config --global init.defaultBranch main
git config --global push.autoSetupRemote true
git config --global pull.rebase true
git config --global rebase.autoStash true
git config --global rerere.enabled true
git config --global diff.algorithm histogram

log "done: $(for t in fd shellcheck shfmt tree sqlite3 just ast-grep; do command -v "$t" >/dev/null && printf '%s ' "$t"; done)"
exit 0
